CREATE OR REPLACE FUNCTION nexus.reaper_expire_quarantine( p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_cutoff text, p_row_limit int ) RETURNS TABLE(expired bigint, protected_count bigint) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_origin_id bigint; v_quar_id bigint; -- RDR-229 P3.7 (vectors-086): read once, at the top of the call, as vectors-083-5 reads it; from gate 3 a row with no -- origin_collection_id key is never deleted (it leaks), and a row's own origin id protects it whatever label the caller passed v_latched boolean := EXISTS (SELECT 1 FROM nexus.rdr229_gate_latch WHERE gate = 'gate3'); v_chashes bytea[]; v_protected bigint; v_deleted bytea[]; v_expired bigint; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'reaper_expire_quarantine: p_row_limit must be positive, got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
PERFORM set_config('lock_timeout', '2000', true);
-- Past the cutoff, the engine's own rows (tagged by the move, tag still valid, from this origin) that a -- manifest row of the origin still names: never deleted, counted so the caller can label them. SELECT count(*) INTO v_protected FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND nexus.reaper_owns_quarantined_row(c.metadata) AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_latched OR c.metadata->'origin_collection_id' IS NOT NULL) AND c.metadata->>'quarantined_at' <= p_cutoff AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '') OR (jsonb_typeof(c.metadata->'origin_collection_id') = 'number' AND c.metadata->'origin_collection_id' = to_jsonb(m.collection_id))) AND m.chash = c.chash);
SELECT COALESCE(array_agg(s.chash ORDER BY s.chash), '{}'::bytea[]) INTO v_chashes FROM ( SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND nexus.reaper_owns_quarantined_row(c.metadata) AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_latched OR c.metadata->'origin_collection_id' IS NOT NULL) AND c.metadata->>'quarantined_at' <= p_cutoff AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '') OR (jsonb_typeof(c.metadata->'origin_collection_id') = 'number' AND c.metadata->'origin_collection_id' = to_jsonb(m.collection_id))) AND m.chash = c.chash) ORDER BY c.chash LIMIT p_row_limit) s;
IF COALESCE(array_length(v_chashes, 1), 0) = 0 THEN RETURN QUERY SELECT 0::bigint, v_protected; RETURN; END IF;
-- The delete re-checks every condition, so a chunk a writer re-referenced or re-moved since the read above -- survives, and the count returned is what this statement really deleted. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) AND nexus.reaper_owns_quarantined_row(c.metadata) AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_latched OR c.metadata->'origin_collection_id' IS NOT NULL) AND c.metadata->>'quarantined_at' <= p_cutoff AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '') OR (jsonb_typeof(c.metadata->'origin_collection_id') = 'number' AND c.metadata->'origin_collection_id' = to_jsonb(m.collection_id))) AND m.chash = c.chash) RETURNING c.chash ) SELECT COALESCE(array_agg(d.chash ORDER BY d.chash), '{}'::bytea[]) INTO v_deleted FROM del d;
v_expired := COALESCE(array_length(v_deleted, 1), 0);
IF v_expired > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_expire_quarantine', p_quarantine_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection), 'engine-reaper', false, v_expired, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_deleted[1:LEAST(v_expired, 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'cutoff', p_cutoff, 'protected', v_protected, 'row_limit', p_row_limit) || CASE WHEN v_expired > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END); END IF;
RETURN QUERY SELECT v_expired, v_protected; END; $$;

