PERFORM set_config('lock_timeout', '2000', true);
-- Past the cutoff, client-moved rows (the reaper does not own them) of this origin that a manifest row of the -- origin still names: never deleted, counted so the caller can label them. SELECT count(*) INTO v_protected FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_marker OR jsonb_typeof(c.metadata->'origin_collection_id') = 'null') AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '')) AND m.chash = c.chash);
SELECT COALESCE(array_agg(s.chash ORDER BY s.chash), '{}'::bytea[]) INTO v_chashes FROM ( SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_marker OR jsonb_typeof(c.metadata->'origin_collection_id') = 'null') AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '')) AND m.chash = c.chash) ORDER BY c.chash LIMIT p_row_limit) s;
IF COALESCE(array_length(v_chashes, 1), 0) = 0 THEN RETURN QUERY SELECT 0::bigint, v_protected; RETURN; END IF;
-- The delete re-checks every condition, so a chunk a writer re-referenced, the reaper re-moved (a fresh tag) -- or the client's own expiry already took since the read above survives or is absent, and the count returned -- is what this statement really deleted. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND (NOT v_marker OR jsonb_typeof(c.metadata->'origin_collection_id') = 'null') AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '')) AND m.chash = c.chash) RETURNING c.chash ) SELECT COALESCE(array_agg(d.chash ORDER BY d.chash), '{}'::bytea[]) INTO v_deleted FROM del d;
v_expired := COALESCE(array_length(v_deleted, 1), 0);
IF v_expired > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_expire_client_quarantine', p_quarantine_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection), 'engine-reaper', false, v_expired, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_deleted[1:LEAST(v_expired, 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'cutoff', p_cutoff, 'protected', v_protected, 'row_limit', p_row_limit, 'population', 'client_moved') || CASE WHEN v_expired > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END); END IF;
RETURN QUERY SELECT v_expired, v_protected; END; $$;
